--region handler
function ActivityMidFestivalStoryDialog:SetSubQuestIndexInNew(subList)
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local curPassMainQuestId = activityComp:GetHomeDojo().mainQuestId

    for i, subQuest in ipairs(checkTable(subList)) do
        ---@type MidFestivalMainQuestLevelVo
        local questLevelVo = subQuest
        if curPassMainQuestId < questLevelVo.id then
            self._subQuestIndex = i
            break
        end
    end
end

function ActivityMidFestivalStoryDialog:UpdateSelectIndex(nextPlaceId)
    local allPass = true
    for index, map in ipairs(self._homeDojo.mapQuest) do
        if checkNumber(map.status) == Constants.MidFestivalMapStatus.NOW then
            allPass = false
            if self._homeDojo:IsReachUnlockDate(map.questId) then
                -- 达到解锁日期，获得下一个子列表的NEW项
                self._selectMapIndex = index
                local subList = ActivityMidFestivalMgr:LoadMainQuestLevelVoByPlaceId(checkString(nextPlaceId))
                if next(subList) ~= nil then
                    self:SetSubQuestIndexInNew(subList)
                else
                    self:SetSubQuestIndexInNew(self.subQuestList)
                end
            else
                -- 未达到解锁日期，索引设置为当前子列表的最后一项
                self._subQuestIndex = #self.subQuestList
            end
            break
        end
    end
    if allPass then
        -- 全通关
        self._subQuestIndex = #self.subQuestList
    end
end

function ActivityMidFestivalStoryDialog:OnPlotPlayingOverHandler()
    -- 播放剧情结束
    self:UpdateSelectIndex()
    local mainQuest = self._homeDojo.mapQuest[self._selectMapIndex]
    self:UnlockNextMapJudge(mainQuest.questId, true)
end

function ActivityMidFestivalStoryDialog:OnBattleOverHandler()
    -- 战斗结束
    self:UpdateSelectIndex()
    local mainQuest = self._homeDojo.mapQuest[self._selectMapIndex]
    self:UnlockNextMapJudge(mainQuest.questId)
end

function ActivityMidFestivalStoryDialog:ShowBackWords(hideAll)
    if checkBool(hideAll) then
        for i = 1, BtnCount do
            local scr = string.format("_btnItem%sScr",i)
            if self[scr] then
                self[scr]:ShowBackWords(false)
            end
        end
        return
    end
    local mapQuest = self._activityMidFestivalComponent:GetHomeDojo().mapQuest
    for i = 1, BtnCount do
        local scr = string.format("_btnItem%sScr",i)
        if self[scr] then
            self[scr]:ShowBackWords(mapQuest[i].status ~= 0)
        end
    end
end

---@param status number @ 0 未解锁 1 已解锁 2 已通关
function ActivityMidFestivalStoryDialog:CommonClickHandler(status, selectIndex, ignore)
    local selectedMap = self._homeDojo.mapQuest[checkNumber(selectIndex)]
    local isNotReachDate = not self._homeDojo:IsReachUnlockDate(selectedMap.questId)
    if status == Constants.MidFestivalMapStatus.LOCK or (status == Constants.MidFestivalMapStatus.NOW and isNotReachDate) then
        local tipInfo = localize("未解锁")
        if isNotReachDate then
            tipInfo = self._homeDojo:TimeCountDownTips(selectedMap.questId)
        else
            local unlockName = self._activityMidFestivalComponent:GetMapUnlockName(selectedMap.questId)
            if string.isEmpty(unlockName) then
                goto start
            end
            tipInfo = localize("通关_name_后解锁", {_name_ = unlockName})
        end
        GameUtils.Toast(tipInfo)
        return
    end

    ::start::

    self.LettersNode.blocksRaycasts = false
    if isNotNull(selectIndex) then
        self.selectIndex = checkNumber(selectIndex)
    end
    self:RefreshLeftTab()
    
    if self.ChapterNode then
        CfUtils.SetActive(self.ChapterNode.gameObject,true)
    end
    
    if isNull(ignore) then
        CfUtils.PlayAnimation(self.Root, "ActivityMidFestivalStory_Chapter")
    end
    self:ShowBackWords(true)
    CfUtils.SetTopCommonCb(function()
        KCookie.Set(Constants.WayOfOpenMidFestivalMapKey, Constants.WayOfOpenMidFestivalMap.NONE)
        CfUtils.ResetNavigatorCustomBackAction()
        self:ShowBackWords(false)
        self.LettersNode.blocksRaycasts = true
        self._subQuestIndex = nil
        CfUtils.PlayAnimation(self.Root, "ActivityMidFestivalStory_ChapterToMain")
        CfUtils.SetActive(self.RightNode, false)
    end)
end

function ActivityMidFestivalStoryDialog:ClickPlotHelper()
    local plotId = self._MainEntryVoList[self._selectMapIndex].refId
    local status = self._activityMidFestivalComponent:MainQuestStatus(checkString(plotId))
    self:CommonClickHandler(status, self._selectMapIndex)
