function ActivityMidFestivalStoryDialog:InitItemCell(view, index)
    local luaIndex = index + 1
    local cell = view:NewListViewItem("Cell")
    local placeVo = self.subQuestList[luaIndex]

    ---@type ActivityMidFestivalLeftTabCellNode
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.MidFestival.StoryDialog.ChapterNode.ActivityMidFestivalLeftTabCellNode")
    scr:Refresh(placeVo, checkNumber(self._subQuestIndex) == luaIndex)
    if (placeVo.status == self.Constants.QUEST_STATUS.NEW and isNull(self._subQuestIndex))     -- 进入页面默认选中最新的
    then
        KCookie.Set(Constants.WayOfOpenMidFestivalMapKey, Constants.WayOfOpenMidFestivalMap.NONE)
        scr:PlaySelectAnim()
        self:RefreshRightPanel(placeVo, checkNumber(placeVo.type) == Constants.MidFestivalMainQuestType.PURE_PLOT)
    end
    scr:SetClickCallback(function()
        self._subQuestIndex = luaIndex
        self:RefreshLeftTab()
    end)

    return cell
end

function ActivityMidFestivalStoryDialog:MainQuestStatusHelper(placeId)
    self.subQuestList = ActivityMidFestivalMgr:LoadMainQuestLevelVoByPlaceId(checkString(placeId))

    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local curPassMainQuestId = activityComp:GetHomeDojo().mainQuestId
    local isNew = true
    for _, questLevel in ipairs(self.subQuestList) do
        ---@type MidFestivalMainQuestLevelVo
        local questLevelVo = questLevel
        if curPassMainQuestId < questLevelVo.id then
            if isNew then
                isNew = false
                questLevelVo.status = self.Constants.QUEST_STATUS.NEW -- 新解锁
            else
                questLevelVo.status = self.Constants.QUEST_STATUS.LOCK -- 锁定
            end
        else
            questLevelVo.status = self.Constants.QUEST_STATUS.PASS -- 已通关
        end
    end
end

function ActivityMidFestivalStoryDialog:UnlockNextMapJudge(mapId, ignore)
    local subQuestList = ActivityMidFestivalMgr:LoadMainQuestLevelVoByPlaceId(checkString(mapId))
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local curPassMainQuestId = activityComp:GetHomeDojo().mainQuestId

    local allPass = true
    for _, questLevel in ipairs(subQuestList) do
        ---@type MidFestivalMainQuestLevelVo
        local questLevelVo = questLevel
        if curPassMainQuestId < questLevelVo.id then
            allPass = false
            break
        end
    end
    
    if allPass and self._OpenFromBattleOver then
        -- 本主线地点已经全部通关，刷新地点解锁信息
        self._homeDojo:UpdateMapQuestStatus(mapId, Constants.MidFestivalMapStatus.PASS)   -- 已通关

        -- 解锁下一地点
        local nextPlaceId = mapId + 1
        if self._homeDojo:IsReachUnlockDate(nextPlaceId) then
            self._homeDojo:UpdateMapQuestStatus(nextPlaceId, Constants.MidFestivalMapStatus.NOW)   -- 已解锁
        end

        self:RefreshUI()
        self:ShowBackWords(true)
        self:UpdateSelectIndex(nextPlaceId)
    end
    local mainQuest = self._homeDojo.mapQuest[self._selectMapIndex]
    self:CommonClickHandler(mainQuest.status, self._selectMapIndex, ignore)
end

function ActivityMidFestivalStoryDialog:RefreshLeftTab()
    local selectedQuest = self._mainQuestList[self.selectIndex]

    self:MainQuestStatusHelper(selectedQuest.questId)
    local count = table.count(checkTable(self.subQuestList))

    local showIndex = 0
    for idx,v in pairs(self.subQuestList) do
        if v.status == self.Constants.QUEST_STATUS.NEW  then
            showIndex = idx
            break
        end
    end

    if not self.LeftTabItem.IsListViewInit then
        self.LeftTabItem:InitListView(count, Bind(self, self.InitItemCell))
    else
        GameUtils.ReloadData(self.LeftTabItem, count)
    end

    if isNull(self._subQuestIndex) then
        self.LeftTabItem:MovePanelToItemIndex(showIndex - 1)
    end

end

function ActivityMidFestivalStoryDialog:RefreshUI()
    for i = 1, BtnCount do
        local scr = string.format("_btnItem%sScr",i)
        if self[scr] then
            self[scr]:Refresh()
        end
    end
    self._isWaiting = false
end
