--region public
function ActivityMidFestivalStoryDialog:InitData()
    self._MainEntryVoList = self:GetMainEntryVo()
    self._homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    self._mainQuestList = self._homeDojo.mapQuest
    self:RefreshUI()
end

function ActivityMidFestivalStoryDialog:GetMainEntryVo()
    local allVo = ActivityMidFestivalMgr:LoadMainEntryVo()
    local activityDojo = self._activityMidFestivalComponent:GetActivityDojo()
    local data = {}
    for i, v in ipairs(allVo) do
        if v.activityId == activityDojo.activityContentId then
            table.insert(data,v)
        end
    end
    return data
end
